UPDATE characters SET description = '主人公のクラス（D組）の担任教師。もともとクラスに対して無関心で、クラス対抗戦では生徒たちを助けるための行動をほとんど取らず、概してやる気のないまま過ごしている。', tags = '{"お姉さん","教師","社会人","マイペース"}' WHERE character_id = 'CH003781';
