UPDATE characters SET description = 'チルチャックはライオスのパーティの一員だ。彼は東大陸出身のハーフフォットである。チルチャックは抜け目なく、現実的で、口が鋭い。前払いがなければ仕事を引き受けない。 得意分野は錠前開けと、罠の見極め・解除だ。マルシルほどではないが、モンスターを食べることには比較的寛容な方だが、彼女と同様にヒューマノイドに関しては断固として拒否する。基本的にはパーティーの行動に同調するが、命に関わるような行動をとった際には率直に意見を述べる。彼の役割は……', tags = '{"茶髪","ショートヘア","小柄","白肌","細身","真面目","クール","社会人","人外"}' WHERE character_id = 'CH003707';
UPDATE characters SET description = '種族：人間　ランク：レギュラー　役職：ライトベアラー　クン・アグエロ・アグニスは、クン家出身のEランク・レギュラーであり、しばしば単に「クン」と呼ばれる。『タワー・オブ・ゴッド』の主要主人公の一人である「25番目のバム」の親友である。  クンは卓越した知性を大いに頼りにしているが、それが彼の唯一の強みというわけではない。彼は並外れた身体能力も持ち合わせており、熟練した光の担い手でもある。戦闘における彼の能力は否定できない。', tags = '{"主人公","天才","クール","真面目","ショタ"}' WHERE character_id = 'CH013782';
UPDATE characters SET description = 'ジャ・ワンナンは、塔全体の王になることを目指している。彼は、誰の願望よりも、自らの生きる決意を何よりも大切にしている。彼は、諦めてしまった者たちとは違い、塔の各階を登り続け、塔の真の頂点に到達するつもりだ。', tags = '{"主人公"}' WHERE character_id = 'CH013783';
UPDATE characters SET description = '種族：人間　ランク：エクストラ　レイチェル（別名ミシェル・ライト）は、バームの「洞窟」を訪ねてくれた唯一の人物であり、彼にとって最良かつ唯一の友人だった。彼女は「夜」を恐れているため、タワーの頂上で待ち受ける伝説の報酬の一つである星々を、切望している。', tags = '{"ヒロイン"}' WHERE character_id = 'CH013784';
UPDATE characters SET description = 'カン・ホリャンはEランクの正規兵であり、槍使いである。彼は巨体で無口な男で、右肩の上に奇妙な印が浮かんでおり、それが原因で、普段ならまるで片翼の天使のように見える。彼の上半身、そしておそらく下半身も、ボタンが付いた黒い包帯で巻かれているようだ。', tags = '{"黒髪","長身","筋肉質","包帯","無口"}' WHERE character_id = 'CH013785';
