UPDATE characters SET description = '天元（てんげん）  中国の自然観のひとつで、万物成育の源である、天の元気。 天子、君主のこと。 万物の素、元素（古代の意味での）。 天元術 - 中国・日本の数学技術。 算命学・四柱推命で天に配される十干（天干）の総称および別名。', tags = NULL WHERE character_id = 'CH011291';
UPDATE characters SET description = '虎杖 悠仁（いたどり ゆうじ）は、芥見下々による日本の漫画『呪術廻戦』に登場する架空の人物（主人公）。並外れた身体能力を備えた少年である悠仁は、特級呪物・両面宿儺の指を食べたことがきっかけで、呪術の世界に足を踏み入れる。悠仁は『NARUTO -ナルト-』の主人公・うずまきナルトや『BLEACH』の主人公・黒崎一護の影響を受けて制作された。アニメ版では榎木淳弥が声優を務めた。多くの評論家が悠仁の成長', tags = '{"黒髪","ショタ","主人公","中学生","格闘家","人外"}' WHERE character_id = 'CH011283';
