UPDATE characters SET description = '一ノ瀬のクラスの生徒。', tags = NULL WHERE character_id = 'CH003787';
UPDATE characters SET description = '綾小路は、目立たず、控えめな学生である。彼は極めて聡明であり、周囲の人々の感情を洞察する深い洞察力を持っていることが示されている。 入試以前の彼の人生については、ほとんど何も知られていない。彼は極めて計算高く、超人的な知性、洞察力、そして強さを備えている。戦闘に長けており、周囲の人々を容易に操ることができる。彼は友人たちを非常に大切にしており、できる限り彼らを守ろうとしている。', tags = '{"黒髪","JK/高校生","主人公","高校生","クール","天才","格闘家"}' WHERE character_id = 'CH003742';
UPDATE characters SET description = '綾小路の隣に座っている美しい少女。友情に関しては綾小路とは正反対で、友情を軽視し、友達を作る必要性を感じていないため、クラスメートとはあまり交流を持たない。自分がD組に配属されたことに納得しておらず、A組への昇格を目指している。', tags = '{"黒髪","ロングヘア","JK/高校生","制服","クール","ライバル","高校生"}' WHERE character_id = 'CH003744';
UPDATE characters SET description = 'ホナミを一言で表すなら、彼女は心から親切で、慈愛に満ち、根っからの平和主義者であり、卑怯な手段や暴力に反対していると言えるでしょう。 彼女の主な特徴の一つは、利他的で人を支える性格であり、優れた対人スキルと、生まれつき人を大切にする姿勢が相まって形成されています。また、ホナミはカリスマ性がありエネルギッシュな人物でもあり、他の多くの上流階級の学生とは異なり、下層階級の人々に対してもその優しく温厚な人柄を惜しみなく示しています。', tags = '{"JK/高校生","お嬢様","元気","ヒロイン"}' WHERE character_id = 'CH003745';
UPDATE characters SET description = '坂柳有栖は、葛城康平と共に1年A組の学級委員の一人である。彼女は先天性心疾患を患っており、そのせいで身体能力に制限がある。   彼女は「流れに身を任せる」ような態度の持ち主のようで、ほとんどの状況を文句一つ言わずに受け入れているが、葛城がクラスの成績について言及した際には、退屈な状況が嫌だと口にした。保守的な姿勢をとる葛城康平とは異なり、有栖は革新的な考え方を持ち合わせている。二人は力を合わせて、クラスを効果的に率いている。', tags = '{"小柄","JK/高校生","制服","委員長","マイペース"}' WHERE character_id = 'CH003743';
UPDATE characters SET description = '所属：イーストン・マジック・アカデミー　職業：学生　ランス・クラウンは、入学試験で1位を獲得し、2つのマークを持っていることで知られる、イーストン・マジック・アカデミーの学生である。  幼い頃のランスは、たとえ喧嘩に巻き込まれることになっても、他人から不当な扱いを受けている人々を庇おうとする、非常に思いやりのある人物だった。ランスは妹を何よりも大切にしており、妹が連れ去られるのを防ぐために「神の予言者」になることを誓っている。', tags = '{"長身","魔法使い","天才"}' WHERE character_id = 'CH003800';
UPDATE characters SET description = 'ラブ・キュートは、イーストン・マジック・アカデミーの2年生です。彼女は「マギア・ルプス」の第五の牙です。', tags = '{"JK/高校生","魔法使い"}' WHERE character_id = 'CH003803';
UPDATE characters SET description = '所属：イーストン魔法学院　職業：学生　レモン・アーバインは、イーストン魔法学院の1年生です。短いブロンドの髪にオレンジ色のリボンを結んでいます。右目の下には、半月形のカーブを描いた直線のマークがあります。普段はイーストン魔法学院の制服を着ています。  レモンは少しお調子者だが、心根は誠実で、他人を裏切るようなことは到底できないようだ。また、とても臆病で、人との会話では話を大げさに言いがちだ。', tags = '{"金髪","ショートヘア","リボン","制服","魔法使い","天然","ドジ","ハジデレ"}' WHERE character_id = 'CH003799';
UPDATE characters SET description = 'レナトス・リボルは、神の予言者であり、魔法局の傘下組織である「魔法墓地管理局」のメンバーである。', tags = '{"長身","お姉さん","社会人","魔法使い"}' WHERE character_id = 'CH003806';
UPDATE characters SET description = '「イノセント・ゼロ」は、同名の犯罪組織のリーダーであり、本作の主要な敵役である。かつては、ウォールバーグと共にアダム・ジョブズの弟子だった。', tags = '{"おじさん","悪役","不死/不老"}' WHERE character_id = 'CH003804';
UPDATE characters SET description = '所属：イーストン・マジック・アカデミー　職業：学生　ドット・バレットは、イーストン・マジック・アカデミーの1年生であり、『マシュレ』シリーズの主人公の一人である。  ドットは短気で生意気な性格だが、心の底では優しい男であり、自分が間違っていた場合は素直に謝る。また、恋に落ちやすい一面も描かれている。', tags = '{"主人公","ショタ","ツンデレ"}' WHERE character_id = 'CH003798';
UPDATE characters SET description = '神聖なる先見者であり、魔法保安部隊の隊長。この国のほとんどの住民とは異なり、リョウは、自分を感心させさえすれば、魔法を使えない人々に対しても何の偏見も抱かない。また、彼は非常に自尊心が強く、自らをスターだと見なしており、自分の行動をナレーションで語ってしまうほどである。', tags = '{"魔法使い","ナルシスト","社会人"}' WHERE character_id = 'CH003805';
UPDATE characters SET description = 'フィン・エイムズは、イーストン・マジック・アカデミーの1年生で、アドラー寮の寮生である。彼はレイン・エイムズの弟である。フィンはマッシュのルームメイトであり、マッシュにとって最初の、そして最も親しい友人である。', tags = '{"高校生"}' WHERE character_id = 'CH003801';
UPDATE characters SET description = 'このシリーズの主人公。マッシュはイーストン魔法学園の1年生で、アドラー寮の寮生である。魔法の才能は全くないという特異な体質を持つ一方で、超人的な力を持っており、それが学園内で彼を一際際立たせている。  マッシュは普段は物静かで優しい性格だ。しかし、家族や友人が傷つけられているのを見かけると、凄まじい怒りを露わにする。また、極めて純真で従順なため、その性格を悪用されることも多いが、その強さのおかげで、ほぼあらゆる状況を好転させることができる。', tags = '{"黒髪","ショートヘア","主人公","ショタ","中学生","制服","真面目","格闘家","超能力"}' WHERE character_id = 'CH003797';
UPDATE characters SET description = 'ユキの大学の先輩で、国際クラブのメンバー。ドイツ語、英語、日本語の3か国語を話せる。また、世界中を旅することや、子供たちと交流することも好きだ。将来は、各国や異文化について教える教師になりたいと考えている。', tags = '{"大学生","先輩"}' WHERE character_id = 'CH003830';
UPDATE characters SET description = 'イツオミを通じて外の世界について学びたいと願う、聴覚障害のある大学生。', tags = '{"大学生","ヒロイン"}' WHERE character_id = 'CH003831';
UPDATE characters SET description = NULL, tags = NULL WHERE character_id = 'CH003843';
UPDATE characters SET description = '彼はオシの友人の一人だ。', tags = NULL WHERE character_id = 'CH003834';
UPDATE characters SET description = '彼はオシの友人の一人だ。', tags = NULL WHERE character_id = 'CH003832';
UPDATE characters SET description = 'リンは、ユキの大学時代の友人だ。彼女は、ユキとイツオミの関係を心から応援している。また、イツオミのいとこであるキョウヤのことが好きだ。', tags = '{"大学生","ヒロイン"}' WHERE character_id = 'CH003835';
UPDATE characters SET description = 'リングル王国救命チームのリーダー。彼女は治癒魔法使いだが、戦闘能力も非常に高く、かつては騎士団の大隊長を務めていた。彼女は、同じく治癒魔法使いであるウサトを救命チームに強制的に加入させ、右腕として育成している。', tags = '{"お姉さん","魔法使い","騎士","真面目","ヒロイン"}' WHERE character_id = 'CH003845';
UPDATE characters SET description = 'ただ「何か特別なこと」を夢見る、ごく普通の高校生。鈴音や一樹と一緒に学校から帰宅途中、リングル王国への召喚に巻き込まれてしまった。 彼が治癒魔法の才能を持っていることが判明すると、ローズの救命チームに強制的に加入させられる。そこで、地獄のような訓練を経て、強靭な肉体を手に入れることになる。', tags = '{"黒髪","JK/高校生","主人公","高校生","魔法使い","異世界転生","筋肉質"}' WHERE character_id = 'CH003844';
